// DevOps Scroll — Learn, Quiz and Scenarios feeds built from my revision guides, tech-vault and
// my Memos project. Content lives in data/*.js (generated by scripts/build_data.py).
(() => {
  "use strict";

  const LEARN = window.LEARN || [];
  const QUIZ = window.QUIZ || [];
  const SCEN = window.SCENARIOS || [];
  const STORE_KEY = "devopsscroll:v1";

  const $ = (s, r = document) => r.querySelector(s);
  const el = (tag, cls, html) => {
    const n = document.createElement(tag);
    if (cls) n.className = cls;
    if (html != null) n.innerHTML = html;
    return n;
  };
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const shuffle = (a) => { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };

  // ---------------------------------------------------------------- progress (this device only)
  const store = (() => {
    let s = {};
    try { s = JSON.parse(localStorage.getItem(STORE_KEY)) || {}; } catch {}
    s.learn ||= {}; s.quiz ||= {}; s.scen ||= {}; s.ui ||= {};
    let t = null;
    const save = () => { clearTimeout(t); t = setTimeout(() => { try { localStorage.setItem(STORE_KEY, JSON.stringify(s)); } catch {} }, 150); };
    return { s, save };
  })();
  const S = store.s;

  // ---------------------------------------------------------------- block renderer
  function renderBlocks(blocks) {
    return (blocks || []).map(renderBlock).join("");
  }
  function renderBlock(b) {
    switch (b.type) {
      case "p": return `<p>${b.html}</p>`;
      case "html": return b.html;
      case "note": return `<div class="note ${b.kind}">${b.html}</div>`;
      case "pre": return `<pre><code>${esc(b.text)}</code></pre>`;
      case "callout": return `<div class="callout ${b.kind}">${renderBlocks(b.blocks)}</div>`;
      case "list": {
        const heads = b.items.map((i) => /^<b>\d+\.\s/.test(i));
        if (b.ordered && heads.some(Boolean)) {
          // A numbered list whose items are "1. Heading" followed by detail lines: show headings + bullets.
          return `<ul class="plain">${b.items.map((i, k) => `<li class="${heads[k] ? "lh" : ""}">${i}</li>`).join("")}</ul>`;
        }
        const tag = b.ordered ? "ol" : "ul";
        const start = b.ordered && b.start > 1 ? ` start="${b.start}"` : "";
        return `<${tag}${start}>${b.items.map((i) => `<li>${i}</li>`).join("")}</${tag}>`;
      }
      case "table": {
        const rows = b.rows.slice();
        const head = b.head ? rows.shift() : null;
        const th = head ? `<thead><tr>${head.map((c) => `<th>${c}</th>`).join("")}</tr></thead>` : "";
        return `<div class="tbl"><table>${th}<tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;
      }
      default: return "";
    }
  }
  const links = (ls) => ls && ls.length
    ? `<div class="links">${ls.map((l) => `<a href="${esc(l.href)}" target="_blank" rel="noopener">🔧 ${esc(l.label)}</a>`).join("")}</div>` : "";

  function card(innerHTML, extraClass = "") {
    const c = el("article", "card " + extraClass);
    const inner = el("div", "card-inner", innerHTML);
    c.appendChild(inner);
    return c;
  }

  // Cards that become the current one (centre of the viewport) fire `onShow`.
  function watchCurrent(feed, onShow) {
    let raf = 0;
    const check = () => {
      raf = 0;
      const mid = feed.scrollTop + feed.clientHeight / 2;
      for (const c of feed.children) {
        if (c.offsetTop <= mid && c.offsetTop + c.offsetHeight > mid) { if (feed._current !== c) { feed._current = c; onShow(c); } break; }
      }
    };
    feed.addEventListener("scroll", () => { if (!raf) raf = requestAnimationFrame(check); }, { passive: true });
    feed._check = check;
  }

  // ---------------------------------------------------------------- toolbar helpers
  const toolbar = $("#toolbar");
  function chips(defs, active, onPick) {
    return defs.map((d) => {
      const b = el("button", "chip" + (d.wide ? " wide" : ""));
      b.type = "button";
      b.innerHTML = esc(d.label) + (d.n != null ? `<span class="n">${d.n}</span>` : "");
      b.setAttribute("aria-pressed", String(d.id === active));
      b.onclick = () => onPick(d.id);
      return b;
    });
  }

  // ================================================================= LEARN
  const learn = {
    feed: $("#view-learn"),
    mode: S.ui.learnMode || "module",
    module: LEARN.find((m) => m.id === S.ui.learnModule) || LEARN[0],

    seen(m) { return (S.learn[m.id] ||= { seen: {}, last: 0 }); },
    pct(m) { const s = this.seen(m); return Math.round((Object.keys(s.seen).length / m.cards.length) * 100); },

    toolbar() {
      toolbar.replaceChildren(
        ...chips([{ id: "module", label: `📖 ${this.module.num ? this.module.num + ". " : ""}${this.module.title}`, wide: true }],
          this.mode === "module" ? "module" : "", () => this.mode === "module" ? this.openSheet() : this.setMode("module")),
        ...chips([{ id: "mix", label: "🔀 Mix" }], this.mode, () => this.setMode("mix")),
        ...chips([{ id: "list", label: "☰ Modules" }], "", () => this.openSheet()),
      );
    },

    setMode(mode) {
      this.mode = S.ui.learnMode = mode; store.save();
      this.render();
    },

    open(m, idx) {
      this.module = m; this.mode = "module";
      S.ui.learnModule = m.id; S.ui.learnMode = "module"; store.save();
      this.render(idx);
    },

    render(startIdx) {
      this.toolbar();
      const f = this.feed;
      f.replaceChildren();
      f._current = null;
      if (this.mode === "mix") return this.renderMix();
      const m = this.module, s = this.seen(m);
      f.appendChild(this.cover(m));
      m.cards.forEach((c, i) => f.appendChild(this.cardEl(m, c, i)));
      f.appendChild(this.endCard(m));
      const idx = startIdx ?? s.last ?? 0;
      requestAnimationFrame(() => {
        const target = idx > 0 ? f.children[idx + 1] : f.children[0];
        f.scrollTop = target ? target.offsetTop : 0;
        f._check();
      });
    },

    renderMix() {
      const f = this.feed;
      const all = [];
      LEARN.forEach((m) => m.cards.forEach((c, i) => all.push([m, c, i])));
      // Favour cards not seen yet.
      const unseen = shuffle(all.filter(([m, , i]) => !this.seen(m).seen[i]));
      const seen = shuffle(all.filter(([m, , i]) => this.seen(m).seen[i]));
      const deck = unseen.concat(seen);
      let pos = 0;
      const more = () => { deck.slice(pos, pos + 15).forEach(([m, c, i]) => f.appendChild(this.cardEl(m, c, i, true))); pos += 15; };
      more();
      f._more = () => { if (pos < deck.length && f.scrollTop + f.clientHeight * 4 > f.scrollHeight) more(); };
      f.scrollTop = 0;
      requestAnimationFrame(() => f._check());
    },

    cover(m) {
      const done = this.pct(m);
      const c = card(`
        <div class="meta"><span class="badge ${m.guide === "aws" ? "blue" : "accent"}">${esc(m.guideTitle)}</span><span>${esc(m.part)}</span></div>
        <div class="big">${m.guide === "aws" ? "☁️" : "🛠️"}</div>
        <h2>${m.num ? `Module ${esc(m.num)} · ` : ""}${esc(m.title)}${m.key ? " 🧠" : ""}</h2>
        <p class="muted">${m.cards.length} cards · about ${Math.max(1, Math.round(m.cards.length * 0.6))} min · ${done}% seen</p>
        <div class="progress"><i style="width:${done}%"></i></div>
        ${m.links.length ? `<div class="label">In your Memos repo</div>${links(m.links)}` : ""}
        <p class="muted">Scroll down to start ↓</p>`, "cover");
      c.querySelector(".card-inner").classList.add("cover");
      c._learn = { m, i: -1 };
      return c;
    },

    cardEl(m, c, i, mix = false) {
      const total = m.cards.length;
      const node = card(`
        <div class="meta">
          <span class="badge ${m.guide === "aws" ? "blue" : "accent"}">${m.num ? esc(m.num) + ". " : ""}${esc(m.title)}</span>
          <span>${i + 1} / ${total}</span>
        </div>
        ${mix ? "" : `<div class="progress"><i style="width:${((i + 1) / total) * 100}%"></i></div>`}
        <h2>${esc(c.title)}${c.part ? `<small>${esc(c.part)}</small>` : ""}</h2>
        <div class="body">${renderBlocks(c.blocks)}</div>
        ${mix ? `<button type="button" class="btn" data-open>Open this module →</button>` : ""}`);
      node._learn = { m, i };
      const ob = node.querySelector("[data-open]");
      if (ob) ob.onclick = () => this.open(m, i);
      return node;
    },

    endCard(m) {
      const idx = LEARN.indexOf(m);
      const next = LEARN[idx + 1];
      const node = card(`
        <div class="big center">✅</div>
        <h2 class="center">Module done: ${esc(m.title)}</h2>
        <p class="muted center">Test yourself on it, or keep going.</p>
        ${next ? `<button type="button" class="btn primary" data-next>Next: ${next.num ? esc(next.num) + ". " : ""}${esc(next.title)} →</button>` : ""}
        <button type="button" class="btn" data-quiz>🧠 Quiz me on ${esc(quiz.topicFor(m))}</button>
        <button type="button" class="btn" data-list>☰ All modules</button>`);
      node.querySelector(".card-inner").style.textAlign = "center";
      if (next) node.querySelector("[data-next]").onclick = () => this.open(next, 0);
      node.querySelector("[data-quiz]").onclick = () => { quiz.setTopic(quiz.topicFor(m)); tabs.show("quiz"); };
      node.querySelector("[data-list]").onclick = () => this.openSheet();
      return node;
    },

    onShow(c) {
      if (!c._learn || c._learn.i < 0) return;
      const { m, i } = c._learn;
      const s = this.seen(m);
      s.seen[i] = 1;
      if (this.mode === "module") s.last = i;
      store.save();
    },

    openSheet() {
      const body = $("#sheetBody");
      body.replaceChildren();
      $("#sheetTitle").textContent = "Modules";
      let lastHead = "";
      LEARN.forEach((m) => {
        const head = m.guideTitle;
        if (head !== lastHead) { body.appendChild(el("h3", "", esc(head))); lastHead = head; }
        const pct = this.pct(m);
        const b = el("button", "mod", `<span class="num">${esc(m.num || "•")}</span><span>${esc(m.title)}${m.key ? " 🧠" : ""}</span>
          <span class="pct">${pct}%</span><div class="progress"><i style="width:${pct}%"></i></div>`);
        b.type = "button";
        b.setAttribute("aria-current", String(m === this.module));
        b.onclick = () => { sheet.close(); this.open(m); };
        body.appendChild(b);
      });
      sheet.showModal();
      body.querySelector('[aria-current="true"]')?.scrollIntoView({ block: "center" });
    },
  };

  // ================================================================= QUIZ
  const QUIZ_TOPICS = ["Linux", "Networking", "Git", "Docker", "AWS", "Terraform", "CI/CD", "Kubernetes", "Azure"];
  const quiz = {
    feed: $("#view-quiz"),
    topic: S.ui.quizTopic || "all",
    deck: [], pos: 0,
    session: { right: 0, seen: 0 },

    topicFor(m) {
      const t = (m.title + " " + m.part).toLowerCase();
      const map = [["terraform", "Terraform"], ["infrastructure as code", "Terraform"], ["docker", "Docker"], ["container", "Docker"],
        ["ci/cd", "CI/CD"], ["git", "Git"], ["linux", "Linux"], ["bash", "Linux"], ["network", "Networking"], ["dns", "Networking"]];
      for (const [k, v] of map) if (t.includes(k)) return v;
      return "AWS";
    },

    pool(topic = this.topic) {
      if (topic === "all") return QUIZ;
      if (topic === "defs") return QUIZ.filter((q) => q.kind === "definition");
      if (topic === "missed") return QUIZ.filter((q) => { const r = S.quiz[q.id]; return r && r.w > (r.r || 0); });
      if (topic === "quick") return QUIZ.filter((q) => q.quick || q.practice);
      return QUIZ.filter((q) => q.topic === topic && q.kind !== "definition")
        .concat(QUIZ.filter((q) => q.topic === topic && q.kind === "definition"));
    },

    toolbar() {
      const missed = this.pool("missed").length;
      const defs = [{ id: "all", label: "All", n: QUIZ.length }, { id: "quick", label: "⚡ Quick-fire" },
        ...(missed ? [{ id: "missed", label: "❌ Missed", n: missed }] : []),
        { id: "defs", label: "📖 Definitions" },
        ...QUIZ_TOPICS.map((t) => ({ id: t, label: t, n: this.pool(t).length }))];
      const stat = el("span", "stat", `✓ ${this.session.right}/${this.session.seen}`);
      stat.id = "quizStat";
      toolbar.replaceChildren(stat, ...chips(defs, this.topic, (id) => this.setTopic(id)));
      toolbar.querySelector('[aria-pressed="true"]')?.scrollIntoView({ inline: "center", block: "nearest" });
    },

    setTopic(t) {
      this.topic = S.ui.quizTopic = t; store.save();
      if (tabs.current === "quiz") this.render(); else this.dirty = true;
    },

    // Unseen and previously-missed cards first; ones you keep getting right sink to the bottom.
    buildDeck() {
      const pool = this.pool();
      const score = (q) => {
        const r = S.quiz[q.id];
        if (!r) return Math.random();                 // unseen
        if (r.w > r.r) return 0.5 + Math.random();    // struggling
        return 1.5 + r.r - r.w + Math.random();       // known
      };
      this.deck = pool.map((q) => [score(q), q]).sort((a, b) => a[0] - b[0]).map((x) => x[1]);
      this.pos = 0;
    },

    render() {
      this.dirty = false;
      this.toolbar();
      const f = this.feed;
      f.replaceChildren();
      f._current = null;
      this.buildDeck();
      if (!this.deck.length) {
        f.appendChild(card(`<h2 class="center">Nothing missed 🎉</h2><p class="muted center">Pick another topic above.</p>`));
        return;
      }
      this.more();
      f.scrollTop = 0;
      requestAnimationFrame(() => f._check());
    },

    more() {
      for (let k = 0; k < 12; k++) {
        if (this.pos >= this.deck.length) { this.buildDeck(); } // loop forever: reshuffle
        this.feed.appendChild(this.cardEl(this.deck[this.pos++]));
      }
    },

    cardEl(q) {
      const r = S.quiz[q.id];
      const hist = r ? `<span>${r.r || 0}✓ ${r.w || 0}✗</span>` : `<span class="badge warn">new</span>`;
      const node = card(`
        <div class="meta"><span class="badge accent">${esc(q.kind === "definition" ? "Definition" : q.topic)}</span>${hist}<span>${esc(q.source)}</span></div>
        <div class="q">${q.q}</div>
        <button type="button" class="reveal">Think of your answer, then tap to reveal</button>
        <div class="answer" hidden>
          <div class="label">Answer</div>
          <div class="body">${renderBlocks(q.a)}</div>
          ${q.more ? `<details class="more"><summary>Full explanation (tech-vault)</summary><div class="body">${q.more}</div></details>` : ""}
          ${q.sourceUrl ? `<div class="links"><a href="${esc(q.sourceUrl)}" target="_blank" rel="noopener">tech-vault ↗</a></div>` : ""}
          <div class="grade">
            <button type="button" class="btn bad" data-g="w">✗ Missed it</button>
            <button type="button" class="btn good" data-g="r">✓ Got it</button>
          </div>
        </div>`);
      node._quiz = q;
      const reveal = node.querySelector(".reveal");
      const ans = node.querySelector(".answer");
      reveal.onclick = () => { reveal.hidden = true; ans.hidden = false; };
      node.querySelectorAll("[data-g]").forEach((b) => b.onclick = () => this.grade(node, b.dataset.g));
      return node;
    },

    grade(node, g) {
      if (node._graded) return;
      node._graded = g;
      const q = node._quiz;
      const r = (S.quiz[q.id] ||= { r: 0, w: 0 });
      r[g] = (r[g] || 0) + 1; r.t = Date.now();
      store.save();
      this.session.seen++; if (g === "r") this.session.right++;
      const st = $("#quizStat"); if (st) st.textContent = `✓ ${this.session.right}/${this.session.seen}`;
      node.querySelectorAll("[data-g]").forEach((b) => { b.disabled = true; if (b.dataset.g === g) b.classList.add("chosen"); });
      if (g === "w") {
        // Bring a missed card back a little later in this session.
        const again = this.cardEl(q);
        const ahead = [...this.feed.children].indexOf(node) + 7;
        this.feed.insertBefore(again, this.feed.children[ahead] || null);
      }
      setTimeout(() => step(this.feed, 1), 450);
    },
  };

  // ================================================================= SCENARIOS
  const scen = {
    feed: $("#view-scen"),
    filter: S.ui.scenFilter || "all",

    pool(f = this.filter) {
      if (f === "all") {
        // Memos scenarios first, then interleave stories and tech-vault.
        const mine = SCEN.filter((s) => s.source === "Your Memos project");
        const stories = SCEN.filter((s) => s.kind === "story");
        const tv = SCEN.filter((s) => s.source.startsWith("tech-vault"));
        const out = [...mine];
        const rest = shuffle([...stories, ...tv]);
        return out.concat(rest);
      }
      if (f === "memos") return SCEN.filter((s) => s.source === "Your Memos project");
      if (f === "stories") return SCEN.filter((s) => s.kind === "story");
      if (f === "tv") return SCEN.filter((s) => s.source.startsWith("tech-vault"));
      if (f === "todo") return SCEN.filter((s) => !S.scen[s.id]);
      return SCEN.filter((s) => s.topic === f);
    },

    toolbar() {
      const topics = [...new Set(SCEN.filter((s) => s.source === "Your Memos project").map((s) => s.topic))];
      const done = Object.keys(S.scen).length;
      const defs = [{ id: "all", label: "All", n: SCEN.length }, { id: "memos", label: "🔧 My Memos project", n: this.pool("memos").length },
        { id: "stories", label: "📖 My stories", n: this.pool("stories").length }, { id: "tv", label: "tech-vault", n: this.pool("tv").length },
        { id: "todo", label: "Not practised", n: SCEN.length - done }, ...topics.map((t) => ({ id: t, label: t, n: this.pool(t).length }))];
      const stat = el("span", "stat", `🎯 ${done}/${SCEN.length}`);
      stat.id = "scenStat";
      toolbar.replaceChildren(stat, ...chips(defs, this.filter, (id) => { this.filter = S.ui.scenFilter = id; store.save(); this.render(); }));
      toolbar.querySelector('[aria-pressed="true"]')?.scrollIntoView({ inline: "center", block: "nearest" });
    },

    render() {
      this.toolbar();
      const f = this.feed;
      f.replaceChildren();
      f._current = null;
      const list = this.pool();
      if (!list.length) f.appendChild(card(`<h2 class="center">All practised 🎉</h2><p class="muted center">Pick another filter above.</p>`));
      list.forEach((s, i) => f.appendChild(this.cardEl(s, i, list.length)));
      f.scrollTop = 0;
      requestAnimationFrame(() => f._check());
    },

    cardEl(s, i, n) {
      const done = S.scen[s.id];
      const node = card(`
        <div class="meta">
          <span class="badge ${s.source === "Your Memos project" ? "accent" : "blue"}">${esc(s.source === "Your Memos project" ? "🔧 Memos" : s.topic)}</span>
          ${s.level ? `<span class="badge">${esc(s.level)}</span>` : ""}
          ${s.source === "Your Memos project" ? (s.topic !== "Memos" ? `<span>${esc(s.topic)}</span>` : "") : `<span>${esc(s.source)}</span>`}
          <span>${i + 1} / ${n}</span>${done ? `<span class="badge warn">practised</span>` : ""}
        </div>
        ${s.title ? `<h2>${esc(s.title)}</h2>` : ""}
        <div class="${s.title ? "body" : "q"}">${s.q}</div>
        <button type="button" class="reveal">Say your answer out loud, then tap for the model answer</button>
        <div class="answer" hidden>
          <div class="label">Model answer</div>
          <div class="body">${renderBlocks(s.answer)}</div>
          ${s.why && s.why.length ? `<div class="label">Why it matters</div><div class="body">${renderBlocks(s.why)}</div>` : ""}
          ${s.links && s.links.length ? `<div class="label">In your repo</div>${links(s.links)}` : ""}
          ${s.sourceUrl ? `<div class="links"><a href="${esc(s.sourceUrl)}" target="_blank" rel="noopener">tech-vault ↗</a></div>` : ""}
          <button type="button" class="btn ${done ? "" : "primary"}" data-done>${done ? "✓ Practised" : "Mark as practised ✓"}</button>
        </div>`);
      node._scen = s;
      const reveal = node.querySelector(".reveal"), ans = node.querySelector(".answer");
      reveal.onclick = () => { reveal.hidden = true; ans.hidden = false; };
      node.querySelector("[data-done]").onclick = (e) => {
        S.scen[s.id] = Date.now(); store.save();
        e.currentTarget.textContent = "✓ Practised"; e.currentTarget.classList.remove("primary");
        const st = $("#scenStat"); if (st) st.textContent = `🎯 ${Object.keys(S.scen).length}/${SCEN.length}`;
        setTimeout(() => step(this.feed, 1), 350);
      };
      return node;
    },
  };

  // ================================================================= NEWS (the original feed, in a frame)
  const news = {
    loaded: false,
    render() {
      toolbar.replaceChildren(el("span", "stat", "Live posts from dev.to and Hacker News"));
      if (this.loaded) return;
      const f = document.createElement("iframe");
      f.src = "feed/index.html";
      f.title = "DevOps news feed";
      $("#view-news").appendChild(f);
      this.loaded = true;
    },
  };

  // ================================================================= tabs & navigation
  const sheet = $("#sheet");
  sheet.addEventListener("click", (e) => { if (e.target === sheet || e.target.closest("[data-close]")) sheet.close(); });

  const views = { learn, quiz, scen, news };
  const rendered = {};
  const tabs = {
    current: null,
    show(name) {
      this.current = name;
      S.ui.tab = name; store.save();
      document.querySelectorAll(".view").forEach((v) => (v.hidden = v.dataset.tab !== name));
      document.querySelectorAll(".tabbar button").forEach((b) => b.setAttribute("aria-current", b.dataset.tab === name ? "page" : "false"));
      const v = views[name];
      if (!rendered[name] || v.dirty) { v.render(); rendered[name] = true; }
      else v.toolbar ? v.toolbar() : v.render();
      const feed = v.feed;
      if (feed) feed.focus({ preventScroll: true });
    },
  };
  document.querySelectorAll(".tabbar button").forEach((b) => (b.onclick = () => tabs.show(b.dataset.tab)));

  function step(feed, dir) { feed.scrollBy({ top: dir * feed.clientHeight, behavior: "smooth" }); }

  // Infinite feeds + "current card" tracking.
  watchCurrent(learn.feed, (c) => learn.onShow(c));
  watchCurrent(quiz.feed, () => {});
  watchCurrent(scen.feed, () => {});
  learn.feed.addEventListener("scroll", () => learn.mode === "mix" && learn.feed._more && learn.feed._more(), { passive: true });
  quiz.feed.addEventListener("scroll", () => {
    const f = quiz.feed;
    if (f.scrollTop + f.clientHeight * 4 > f.scrollHeight) quiz.more();
  }, { passive: true });

  document.addEventListener("keydown", (e) => {
    if (sheet.open || e.metaKey || e.ctrlKey || e.altKey || e.target.matches("input, textarea, select")) return;
    const v = views[tabs.current];
    const feed = v && v.feed;
    if (!feed) return;
    const cur = feed._current;
    switch (e.key) {
      case "j": case "ArrowDown": e.preventDefault(); step(feed, 1); break;
      case "k": case "ArrowUp": e.preventDefault(); step(feed, -1); break;
      case " ": case "Enter": {
        const r = cur && cur.querySelector(".reveal:not([hidden])");
        if (r) { e.preventDefault(); r.click(); } else if (e.key === " ") { e.preventDefault(); step(feed, 1); }
        break;
      }
      case "y": if (cur && cur._quiz) cur.querySelector('[data-g="r"]')?.click(); break;
      case "n": if (cur && cur._quiz) cur.querySelector('[data-g="w"]')?.click(); break;
      case "m": if (tabs.current === "learn") learn.openSheet(); break;
      case "1": tabs.show("learn"); break;
      case "2": tabs.show("quiz"); break;
      case "3": tabs.show("scen"); break;
      case "4": tabs.show("news"); break;
      default: return;
    }
  });

  tabs.show(S.ui.tab && views[S.ui.tab] ? S.ui.tab : "learn");

  // Offline support once installed to the home screen.
  if ("serviceWorker" in navigator && /^https:|^http:\/\/localhost/.test(location.href)) {
    navigator.serviceWorker.register("sw.js").catch(() => {});
  }
})();
